import{_ as t,o,a,d as i}from"./chunks/framework.IehvnstE.js";const u=JSON.parse('{"title":"Анализатор логов","description":"Анализатор логов Minecraft в Stuzhik: главная причина краша по устройству отчёта, шаги с кнопками, которые сверяются со сборкой, история крашей и архив логов для автора мода.","frontmatter":{"description":"Анализатор логов Minecraft в Stuzhik: главная причина краша по устройству отчёта, шаги с кнопками, которые сверяются со сборкой, история крашей и архив логов для автора мода.","head":[["meta",{"name":"keywords","content":"minecraft crash analyzer, stuzhik, стужик, анализ логов minecraft, почему вылетает minecraft, minecraft crash fix, mixin crash, краш репорт minecraft"}]]},"headers":[],"relativePath":"guide/log-analyzer.md","filePath":"guide/log-analyzer.md"}'),e={name:"guide/log-analyzer.md"};function n(l,r,s,g,c,d){return o(),a("div",null,[...r[0]||(r[0]=[i('<h1 id="анализатор-логов" tabindex="-1">Анализатор логов <a class="header-anchor" href="#анализатор-логов" aria-label="Permalink to &quot;Анализатор логов&quot;">​</a></h1><p>Игра упала: анализатор скажет, почему это случилось и что сделать, а кнопки для этого стоят прямо в шагах.</p><p>Он читает сам отчёт о краше: стек вызовов, раздел <code>Mixins in Stacktrace</code> и названные там моды. Виновника он ищет по тому, где упал код, а не по тому, какой мод чаще мелькает в логе. На настоящих крашах из трекеров модов он нашёл <strong>верную причину в 90 случаях из 93</strong> и <strong>ни разу не обвинил не тот мод</strong>. Отчёт пишется на языке интерфейса лаунчера.</p><h2 id="когда-он-запускается" tabindex="-1">Когда он запускается <a class="header-anchor" href="#когда-он-запускается" aria-label="Permalink to &quot;Когда он запускается&quot;">​</a></h2><ul><li><strong>Сам, после краша.</strong> Разбор попадает в «Историю крашей», и анализатор открывается. Даже если окно лаунчера было закрыто, краш всё равно окажется в истории</li><li><strong>Вручную.</strong> Вкладка «Анализ логов» на странице сборки, «Проверить снова» разбирает логи ещё раз</li><li><strong>Без окна.</strong> <code>stuzhik-cli analyze</code> в <a href="/guide/cli.html">консольной версии</a> печатает тот же разбор</li></ul><h2 id="live-monitoring" tabindex="-1">Во время игры <a class="header-anchor" href="#live-monitoring" aria-label="Permalink to &quot;Во время игры {#live-monitoring}&quot;">​</a></h2><p><strong>Ошибки видны ещё до краша</strong>: «Live-мониторинг» в заголовке окна следит за логом, пока игра идёт. Ошибка загрузки (скрипт KubeJS, конфликт mixin) сразу открывает анализатор.</p><h2 id="solutions" tabindex="-1">Главная причина <a class="header-anchor" href="#solutions" aria-label="Permalink to &quot;Главная причина {#solutions}&quot;">​</a></h2><p>Сверху карточка: что случилось, в каком моде и что с этим модом в сборке (какая версия стоит или что его в сборке нет). Под ней «Что сделать»: шаги по порядку, у каждого своя кнопка.</p><ol><li><strong>Обновить.</strong> Анализатор сам проверит, есть ли версия новее для этой сборки, и покажет, до какой обновит. Если новее нет или версия закреплена, он так и напишет вместо кнопки, которая ничего не сделает</li><li><strong>Отключить.</strong> Мод выключается в сборке, «Включить обратно» возвращает его. Уже отключён: шаг так и скажет</li><li><strong>Сообщить автору.</strong> «Архив логов» собирает логи этого запуска в <code>.zip</code>, «Страница мода» и «Трекер ошибок» ведут туда, куда его отправить</li></ol><p>Кнопка сразу показывает, что делает («Обновление…», «Отключение…»). <strong>Результат виден в самом шаге</strong>: «обновлён до …, запустите игру», ошибка тоже под шагом.</p><ul><li>«Как это определено»: строки отчёта, по которым это решено</li><li>«Подробнее и поиск решений»: полное описание проблемы</li></ul><h2 id="еще-нашлось" tabindex="-1">Ещё нашлось <a class="header-anchor" href="#еще-нашлось" aria-label="Permalink to &quot;Ещё нашлось&quot;">​</a></h2><p>Под главной причиной всё остальное, что анализатор узнал в логе: нехватка памяти, повреждённый конфиг, не та Java и другое. Шаги у этих находок тоже сверяются со сборкой, а у строки есть кнопка первого шага, который лаунчер сделает сам:</p><ul><li><strong>Установить.</strong> Недостающий мод ставится в той версии, которую принимает требующий его мод. Стоит, но отключён: шаг предложит «Включить». Не встанет рядом с другим модом сборки: так и скажет</li><li><strong>Обновить.</strong> Зависимость стоит, но не той версии: обновляется эта, вторая копия рядом не ставится</li><li><strong>Удалить файл.</strong> Повреждённый файл настроек мода, ровно тот, что назвал загрузчик (копия остаётся в <code>.backup/config</code>). Настройки мира ищутся в папке <code>serverconfig</code> этого мира</li><li><strong>Исправить.</strong> Остальное, что лаунчер умеет сам: «Увеличить выделенную память», «Переустановить мод» и подобное</li></ul><p>После такого шага у находки пометка «Ожидает перезапуска»: <strong>следующий шаг понадобится, только если краш повторится</strong>. Все шаги находки открывает «Подробнее и поиск решений».</p><div class="tip custom-block"><p class="custom-block-title">Исправить всё разом</p><p>«Исправить все проблемы» показывает, что будет сделано по каждой находке, а «Применить выбранные» делает отмеченное. <strong>Отключение мода там заранее не отмечено</strong>: миры с его блоками без него лучше не открывать.</p></div><p>«Не проблема» скрывает находку в этой сборке, и следующие разборы её больше не предлагают. Вернуть её можно в «Управлении скрытыми».</p><h2 id="run-logs" tabindex="-1">Логи запуска <a class="header-anchor" href="#run-logs" aria-label="Permalink to &quot;Логи запуска {#run-logs}&quot;">​</a></h2><p>Вкладка рядом с «Анализом логов» показывает сами файлы последнего запуска: лог игры, подробный лог, отчёт о краше, падение Java и логи, которые моды пишут в свои папки (KubeJS, CraftTweaker и другие). Файлы старше этого запуска собраны под «Более старые».</p><ul><li><strong>Цвет по уровню.</strong> Трассировка ошибки показана вместе с её записью</li><li><strong>Фильтры.</strong> «Ошибки» и «Ошибки и предупреждения» оставляют только такие записи, с их трассировками</li><li><strong>Поиск.</strong> Совпадения подсвечены, <kbd>Enter</kbd> и <kbd>Shift</kbd>+<kbd>Enter</kbd> ведут к следующему и предыдущему</li><li><strong>«К следующей ошибке»</strong> прокручивает к ближайшей ошибке ниже</li><li><strong>Пока игра идёт</strong>, открытый файл перечитывается сам, а «Следить за концом» держит его последние строки на экране</li><li><strong>Большой файл</strong> (больше 16 МБ) показан с конца: там и лежит последний запуск</li></ul><h2 id="меню-«еще-деиствия»-⋯" tabindex="-1">Меню «Ещё действия» (⋯) <a class="header-anchor" href="#меню-«еще-деиствия»-⋯" aria-label="Permalink to &quot;Меню «Ещё действия» (⋯)&quot;">​</a></h2><ul><li><strong>«Отдельный лог-файл»</strong>: разобрать один из логов сборки, а не последний запуск</li><li><strong>«Открыть лог с диска…»</strong>: любой лог или crash-report, не обязательно из Stuzhik</li><li><strong>«Сохранить отчёт»</strong> и <strong>«Открыть сохранённый отчёт…»</strong>: разбор в файл и обратно</li><li><strong>«Архив логов для автора мода»</strong>: <code>latest.log</code>, конец <code>debug.log</code>, последние crash-report&#39;ы и разбор Stuzhik в одном <code>.zip</code></li><li><strong>«Копировать как Markdown»</strong>: отчёт в буфер обмена, чтобы вставить в чат или issue на GitHub</li><li><strong>«Какие исправления разрешены»</strong>: что лаунчер может применять сам</li></ul><h2 id="история-крашеи" tabindex="-1">История крашей <a class="header-anchor" href="#история-крашеи" aria-label="Permalink to &quot;История крашей&quot;">​</a></h2><p>Вторая вкладка рядом с «Анализом логов»:</p><ul><li><strong>«Статистика»</strong>: сколько было крашей, сколько за неделю, какие моды виноваты чаще и сколько исправлено</li><li><strong>«История»</strong>: каждый краш с его разбором, «Отметить решённым» помечает исправленный</li><li><strong>«Тренды»</strong>: стало крашей больше или меньше</li></ul><p>«Очистить историю» удаляет записи этой сборки.</p><h2 id="если-ничего-не-нашлось" tabindex="-1">Если ничего не нашлось <a class="header-anchor" href="#если-ничего-не-нашлось" aria-label="Permalink to &quot;Если ничего не нашлось&quot;">​</a></h2><p>«Проблем не обнаружено» значит, что в логах нет ничего из того, что анализатор знает и что мешает игре. Тогда соберите <strong>«Архив логов для автора мода»</strong> и отправьте его в <a href="https://t.me/stuzhik_launcher" target="_blank" rel="noreferrer">Telegram</a> или автору мода.</p>',29)])])}const p=t(e,[["render",n]]);export{u as __pageData,p as default};
